css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; overflow: hidden; }
.loader span { position: absolute; top: 12%; left: -18%; width: calc(var(--loader-size) * .1); height: calc(var(--loader-size) * .1); border-radius: 50%; background: radial-gradient(circle, #fff, var(--accent)); box-shadow: 0 0 calc(var(--loader-size) * .1) var(--accent); animation: shoot calc(var(--loader-speed) * 1.6) ease-in infinite; }
.loader span::after { content: ''; position: absolute; right: 55%; top: 50%; width: calc(var(--loader-size) * .55); height: 2px; margin-top: -1px; background: linear-gradient(90deg, transparent, var(--accent-2)); }
@keyframes shoot { 0% { transform: translate(0, 0); opacity: 0; } 15% { opacity: 1; } 85% { opacity: 1; } 100% { transform: translate(calc(var(--loader-size) * 1.4), calc(var(--loader-size) * .72)); opacity: 0; } }
